import pytest

from cfnlint.context import create_context_for_template
from cfnlint.jsonschema import CfnTemplateValidator
from cfnlint.rules.functions.GetAtt import GetAtt
from cfnlint.template import Template


@pytest.fixture(scope="module")
def rule():
    rule = GetAtt()
    yield rule


def test_getatt_provisioned_product_outputs(rule):
    # Minimal template with two ProvisionedProducts; second uses GetAtt Outputs.SomeKey from first
    cfn = Template(
        "",
        {
            "Resources": {
                "SimpleLambda": {
                    "Type": "AWS::ServiceCatalog::CloudFormationProvisionedProduct",
                    "Properties": {
                        "ProductName": "Basic Lambda",
                        "ProvisioningArtifactName": "1.0",
                    },
                },
                "SimpleApiGateway": {
                    "Type": "AWS::ServiceCatalog::CloudFormationProvisionedProduct",
                    "Properties": {
                        "ProductName": "API Gateway",
                        "ProvisioningArtifactName": "1.0",
                        "ProvisioningParameters": [
                            {"Key": "LambdaArn", "Value": {"Fn::GetAtt": ["SimpleLambda", "Outputs.SCLambdaArn"]}},
                        ],
                    },
                },
            }
        },
        regions=["us-east-1"],
    )

    context = create_context_for_template(cfn)
    validator = CfnTemplateValidator({}, context=context, cfn=cfn)

    # Validate that GetAtt does not raise E1010 for Outputs dynamic key
    errs = list(rule.fn_getatt(validator, {"type": "string"}, {"Fn::GetAtt": ["SimpleLambda", "Outputs.SCLambdaArn"]}, {}))
    assert errs == [], f"Expected no errors for dynamic Outputs, got: {errs}"

