import pytest

from cfnlint.rules.functions.GetAttFormat import GetAttFormat
from cfnlint.jsonschema import CfnTemplateValidator
from cfnlint.context import create_context_for_template
from cfnlint.template import Template


@pytest.fixture(scope="module")
def rule():
    rule = GetAttFormat()
    yield rule


def test_getatt_format_exception_for_servicecatalog():
    # Template where a property expecting VPC Id consumes ProvisionedProduct Outputs
    tmpl = {
        "Resources": {
            "VpcProv": {
                "Type": "AWS::ServiceCatalog::CloudFormationProvisionedProduct",
                "Properties": {
                    "ProductName": "VPC",
                    "ProvisioningArtifactName": "1.0",
                },
            },
            "Subnet": {
                "Type": "AWS::EC2::Subnet",
                "Properties": {
                    "VpcId": {"Fn::GetAtt": ["VpcProv", "Outputs.VpcId"]},
                    "CidrBlock": "10.0.0.0/24",
                },
            },
        }
    }

    cfn = Template("", tmpl, ["us-east-1"])
    context = create_context_for_template(cfn)
    validator = CfnTemplateValidator({}, context=context, cfn=cfn)

    # Destination expects AWS::EC2::VPC.Id format; due to resource type exception, no error should be raised
    errs = list(rule.validate(validator, {"format": "AWS::EC2::VPC.Id"}, ["VpcProv", "Outputs.VpcId"], {"format": "AWS::EC2::VPC.Id"}))
    assert errs == [], f"Expected no E1040 errors for ProvisionedProduct Outputs, got: {errs}"

